/**
 * Dropbox Node - Version 1
 * Discriminator: resource=folder, operation=copy
 */


interface Credentials {
  dropboxApi: CredentialReference;
  dropboxOAuth2Api: CredentialReference;
}

/** Copy a file */
export type DropboxV1FolderCopyParams = {
  resource: 'folder';
  operation: 'copy';
/**
 * Means of authenticating with the service
 * @default accessToken
 */
    authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The path of file or folder to copy
 */
    path: string | Expression<string>;
/**
 * The destination path of file or folder
 */
    toPath: string | Expression<string>;
};

export type DropboxV1FolderCopyOutput = {
  metadata?: {
    '.tag'?: string;
    id?: string;
    name?: string;
    parent_shared_folder_id?: string;
    path_display?: string;
    path_lower?: string;
    sharing_info?: {
      no_access?: boolean;
      parent_shared_folder_id?: string;
      read_only?: boolean;
      traverse_only?: boolean;
    };
  };
};

export type DropboxV1FolderCopyNode = {
  type: 'n8n-nodes-base.dropbox';
  version: 1;
  config: NodeConfig<DropboxV1FolderCopyParams> & { credentials?: Credentials };
  output?: Items<DropboxV1FolderCopyOutput>;
};